import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = () => {
  const [latestEntry, setLatestEntry] = useState(null);

  useEffect(() => {
    fetchLatestEntry();
    // Poll every 1 second to keep it responsive to the IoT device
    const interval = setInterval(fetchLatestEntry, 1000);
    return () => clearInterval(interval);
  }, []);

  async function fetchLatestEntry() {
    // Fetch the single most recent record from the database
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("created_at", { ascending: false }) // Newest first
      .limit(1);

    if (error) {
      console.log("Error fetching logs:", error);
    } else if (data && data.length > 0) {
      setLatestEntry(data[0]);
    }
  }

  // --- LOGIC ---
  // The IoT code sends "Entered" when a car enters and "Exited" when it leaves.
  // So, the slot is OCCUPIED only if the latest status is "Entered".
  const isOccupied = latestEntry && latestEntry.status === "Entered";

  return (
    <main className="dashboard-root">
      
      {/* 1. TOP STATS (Big Counters) */}
      <section className="stats-container">
        
        {/* Available Card */}
        <div className="stat-card green">
          <div className="stat-title">Available</div>
          {/* If NOT occupied, we have 1 slot free */}
          <div className="stat-value">{!isOccupied ? 1 : 0}</div>
        </div>

        {/* Occupied Card */}
        <div className="stat-card red">
          <div className="stat-title">Occupied</div>
          {/* If occupied, we have 1 slot busy */}
          <div className="stat-value">{isOccupied ? 1 : 0}</div>
        </div>

      </section>

      {/* 2. MAIN SLOT DISPLAY */}
      <section className="layout-section">
        <div className="layout-header">Live Parking Spot Status</div>
        
        <div className="single-slot-container">
           {/* We pass the whole entry object and the calculated status */}
           <SlotCard 
              slotData={latestEntry} 
              isOccupied={isOccupied} 
           />
        </div>
      </section>

    </main>
  );
};

export default UserDashboard;
